ate-columns: repeat(3, 1fr);\n        gap: 20px;\n      }\n      .field label {\n        display: block;\n        margin-bottom: 8px;\n      }\n      .reason {\n        margin-top: 24px;\n      }\n      .help {\n        font-size: 14px;\n        color: var(--muted);\n        margin: 8px 0;\n      }\n      .submit {\n        margin-top: 24px;\n        background: var(--accent);\n        color: #fff;\n        border: 0;\n        padding: 12px 18px;\n        border-radius: 5px;\n      }\n      [hidden] {\n        display: none !important;\n      }\n      .request-row {\n        display: flex;\n        justify-content: space-between;\n        padding: 16px 0;\n        border-bottom: 1px solid var(--line);\n      }\n      .tabs {\n        background: var(--surface);\n        border-radius: 12px;\n        padding: 16px;\n        margin-bottom: 38px;\n        min-height: 70px;\n      }\n      .tabs button {\n        padding: 10px 24px;\n        background: transparent;\n      }\n      .reason {\n        display: grid;\n        grid-template-columns: 128px 1fr;\n        align-items: center;\n        gap: 24px;\n      }\n      .reason textarea {\n        min-height: 220px;\n      }\n      .reason label span {\n        display: block;\n        font-size: 14px;\n        color: var(--muted);\n      }\n      @media (max-width: 600px) {\n        header,\n        main {\n          padding: 18px 16px;\n        }\n        .fields {\n          grid-template-columns: 1fr;\n        }\n        header nav {\n          gap: 18px;\n        }\n        .reason {\n          grid-template-columns: 100px 1fr;\n          gap: 14px;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <header>\n      <nav aria-label=\"Operations\">\n        <a href=\"#team\">Team</a><a href=\"#time-off\" aria-current=\"page\">Time off</a\n        ><a href=\"#work-orders\">Work orders</a>\n      </nav>\n    </header>\n    <main id=\"time-off\">\n      <h1>Time off</h1>\n      <p class=\"context\">Team · Record a request and arrange shift cover</p>\n      <div class=\"tabs\" role=\"tablist\" aria-label=\"Time off views\">\n        <button\n          type=\"button\"\n          role=\"tab\"\n          id=\"new-tab\"\n          aria-controls=\"new-panel\"\n          aria-selected=\"true\"\n        >\n          New request</button\n        ><button\n          type=\"button\"\n          role=\"tab\"\n          id=\"requests-tab\"\n          aria-controls=\"requests-panel\"\n          aria-selected=\"false\"\n          tabindex=\"-1\"\n        >\n          Requests\n        </button>\n      </div>\n      <section id=\"new-panel\" role=\"tabpanel\" aria-labelledby=\"new-tab\">\n        <form>\n          <div class=\"fields\">\n            <div class=\"field\">\n              <label for=\"worker\">Team member</label\n              ><select id=\"worker\">\n                <option>Aisha Rahman</option>\n                <option>Daniel Tan</option>\n              </select>\n            </div>\n            <div class=\"field\">\n              <label for=\"start\">Start date</label\n              ><input id=\"start\" type=\"date\" value=\"2026-10-20\" required />\n            </div>\n            <div class=\"field\">\n              <label for=\"end\">End date</label\n              ><input id=\"end\" type=\"date\" value=\"2026-10-22\" required />\n            </div>\n          </div>\n          <div class=\"reason\">\n            <label for=\"reason\">Reason <span>(optional)</span></label>\n            <div>\n              <textarea id=\"reason\" rows=\"6\" aria-describedby=\"reason-help\">\nMorning shift cover arranged.</textarea\n              >\n              <p id=\"reason-help\" class=\"help\">\n                Add information the review manager needs. Do not include sensitive personal details.\n              </p>\n            </div>\n          </div>\n          <button class=\"submit\" type=\"submit\">Record request</button>\n          <p role=\"status\" id=\"result\"></p>\n        </form>\n      </section>\n      <section id=\"requests-panel\" role=\"tabpanel\" aria-labelledby=\"requests-tab\" hidden>\n        <h2>Requests</h2>\n        <div class=\"request-row\">\n          <span>Aisha Rahman · 20–22 October</span><span>Approved</span>\n        </div>\n        <a href=\"#team\">Back to Team</a>\n      </section>\n      <p class=\"help\">\n        Illustrative local UI. Actions simulate a request; no backend or production coverage is\n        claimed.\n      </p>\n    </main>\n    <script>\n      const tabs = [...document.querySelectorAll('[role=\"tab\"]')];\n      function activate(tab) {\n        for (const item of tabs) {\n          const active = item === tab;\n          item.setAttribute(\"aria-selected\", String(active));\n          item.tabIndex = active ? 0 : -1;\n          document.getElementById(item.getAttribute(\"aria-controls\")).hidden = !active;\n        }\n      }\n      for (const tab of tabs) {\n        tab.addEventListener(\"click\", () => activate(tab));\n        tab.addEventListener(\"keydown\", (event) => {\n          if (event.key === \"ArrowRight\" || event.key === \"ArrowLeft\") {\n            event.preventDefault();\n            const next =\n              tabs[\n                (tabs.indexOf(tab) + (event.key === \"ArrowRight\" ? 1 : tabs.length - 1)) %\n                  tabs.length\n              ];\n            activate(next);\n            next.focus();\n          }\n        });\n      }\n      document.querySelector(\"form\").addEventListener(\"submit\", (event) => {\n        event.preventDefault();\n        document.getElementById(\"result\").textContent =\n          \"Request recorded for \" + document.getElementById(\"worker\").value;\n      });\n    </script>\n  </body>\n</html>\n",
